document.addEventListener('DOMContentLoaded', function() {
    const loginForm = document.getElementById('loginForm');
    const passwordInput = document.getElementById('password');
    const togglePasswordBtn = document.getElementById('togglePassword');
    const loadingOverlay = document.getElementById('loadingOverlay');
    let turnstileWidgetId = null;
    let turnstileWaiter = null;

    function initTurnstileWidget() {
        if (!window.turnstile || turnstileWidgetId !== null) return;
        const el = document.getElementById('loginCaptcha')
            || document.querySelector('.cf-turnstile')
            || document.querySelector('.g-recaptcha');
        const siteKey = (el && el.dataset && el.dataset.sitekey) ? el.dataset.sitekey : (window.AUTH_CAPTCHA_SITE_KEY || '');
        if (!el || !siteKey) return;
        turnstile.ready(() => {
            if (turnstileWidgetId !== null) return;
            turnstileWidgetId = turnstile.render(el, {
                sitekey: siteKey,
                size: 'normal',
                execution: 'execute',
                appearance: 'interaction-only',
                callback: (token) => {
                    if (turnstileWaiter) {
                        const cb = turnstileWaiter;
                        turnstileWaiter = null;
                        cb(token || '');
                    }
                },
                'error-callback': () => {
                    if (turnstileWaiter) {
                        const cb = turnstileWaiter;
                        turnstileWaiter = null;
                        cb('');
                    }
                },
                'expired-callback': () => {
                    if (turnstileWaiter) {
                        const cb = turnstileWaiter;
                        turnstileWaiter = null;
                        cb('');
                    }
                }
            });
        });
    }

    async function getTurnstileToken() {
        if (!window.turnstile) return '';
        initTurnstileWidget();
        if (turnstileWidgetId === null) return '';
        return new Promise((resolve) => {
            const timer = setTimeout(() => resolve(''), 10000);
            turnstileWaiter = (token) => {
                clearTimeout(timer);
                resolve(token || '');
            };
            try { turnstile.execute(turnstileWidgetId); } catch (_) { clearTimeout(timer); resolve(''); }
        });
    }

    // Toggle password visibility
    if (togglePasswordBtn && passwordInput) {
        togglePasswordBtn.addEventListener('click', function() {
            const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
            passwordInput.setAttribute('type', type);

            const icon = togglePasswordBtn.querySelector('i');
            if (icon) {
                if (type === 'password') {
                    icon.classList.remove('fa-eye-slash');
                    icon.classList.add('fa-eye');
                } else {
                    icon.classList.remove('fa-eye');
                    icon.classList.add('fa-eye-slash');
                }
            }
        });
    }

    // Form submission
    if (!loginForm) {
        return;
    }

    loginForm.addEventListener('submit', async function(e) {
    e.preventDefault();

    const formData = new FormData(loginForm);
    const creds = Object.fromEntries(formData);

    const recaptchaToken = await getTurnstileToken();
    if (!recaptchaToken) {
        new Dialog('Error', 'Please complete the captcha.', { text: 'Okay', action: () => { }, color: '#ff3333' });
        return;
    }

    loadingOverlay.style.display = 'block';

    const data = new FormData(loginForm);
    data.append('cf-turnstile-response', recaptchaToken);
    data.append('g-recaptcha-response', recaptchaToken);
    
    fetch('https://apilageai.lk/api/auth.php?act=login', {
        method: 'POST',
        body: data
    })
    .then(response => response.json())
    .then(data => {
        loadingOverlay.style.display = 'none';
        
        if (data.e) {
            if (window.turnstile && turnstileWidgetId !== null) turnstile.reset(turnstileWidgetId);
            if (data.resend && data.email) {
                if (typeof showVerificationModal === 'function') {
                    showVerificationModal(data.email, data.m);
                } else {
                    new Dialog(
                        'Email Verification Required',
                        data.m + '\n\nPlease check your email for the verification link.',
                        { 
                            text: 'Resend Email', 
                            action: () => { 
                                resendVerificationEmail(data.email);
                            }, 
                            color: '#667eea' 
                        }
                    );
                }
            } else {
                new Dialog('Error', data.m, { text: 'Okay', action: () => { }, color: '#ff3333' });
            }
        } else {
            new Dialog('Success', 'Login successful! Redirecting...', { text: 'Continue', action: () => { }, color: '#28a745' });
            setTimeout(() => { window.location.href = "https://apilageai.lk/app"; }, 1000);
        }
    })
    .catch(error => {
        loadingOverlay.style.display = 'none';
        if (window.turnstile && turnstileWidgetId !== null) turnstile.reset(turnstileWidgetId);
        console.error('Login error:', error);
        new Dialog('Error', 'Login failed. Please check your connection and try again.', { text: 'Retry', action: () => { }, color: '#ff3333' });
    });
});

    // Helper function to resend verification email
    function resendVerificationEmail(email) {
        loadingOverlay.style.display = 'block';
        
        const formData = new FormData();
        formData.append('email', email);
        
        fetch('https://apilageai.lk/auth/resend-verification', {
            method: 'POST',
            body: formData
        })
        .then(response => response.json())
        .then(data => {
            loadingOverlay.style.display = 'none';
            
            if (data.e) {
                new Dialog(
                    'Error',
                    data.m,
                    { text: 'Okay', action: () => { }, color: '#ff3333' }
                );
            } else {
                new Dialog(
                    'Success',
                    'Verification email sent! Please check your inbox.',
                    { text: 'Okay', action: () => { }, color: '#28a745' }
                );
            }
        })
        .catch(error => {
            loadingOverlay.style.display = 'none';
            console.error('Resend error:', error);
            
            new Dialog(
                'Error',
                'Failed to resend verification email. Please try again.',
                { text: 'Okay', action: () => { }, color: '#ff3333' }
            );
        });
    }

    // Make resend function globally accessible
    window.resendVerificationEmailFromLogin = resendVerificationEmail;
});
